get_ipython().run_cell_magic('writefile', '-a services.py', '\ndef sync_sent_emails_to_history():\n    """\n    نسخة مصححة تمنع التكرار نهائياً باستخدام ملف تتبع المعرفات (Processed IDs).\n    """\n    processed_file = "processed_sent_ids.txt"\n    \n    # تحميل المعرفات التي تمت معالجتها سابقاً\n    processed_ids = set()\n    if os.path.exists(processed_file):\n        with open(processed_file, \'r\', encoding=\'utf-8\') as f:\n            processed_ids = set(f.read().splitlines())\n\n    updates_made = False # متغير لنعرف هل نحتاج إعادة بناء القاعدة أم لا\n\n    try:\n        # قراءة السجل المحلي\n        history_file = "email_history.txt"\n        history_content = ""\n        if os.path.exists(history_file):\n            with open(history_file, \'r\', encoding=\'utf-8\') as f:\n                history_content = f.read()\n\n        mail = imaplib.IMAP4_SSL(IMAP_SERVER)\n        mail.login(GMAIL_EMAIL, APP_PASSWORD)\n        \n        # تحديد مجلد المرسل\n        sent_folder = None\n        for folder in [\'"[Gmail]/Sent Mail"\', \'"[Gmail]/Sent"\', \'Sent\', \'البريد المرسل\']:\n            try:\n                status, _ = mail.select(folder)\n                if status == \'OK\':\n                    sent_folder = folder\n                    break\n            except: continue\n        \n        if not sent_folder: return False # Return False indicates no updates\n\n        # فحص آخر 10 رسائل فقط (للسرعة)\n        status, messages = mail.search(None, \'ALL\')\n        if status != \'OK\': return False\n\n        sent_msg_ids = messages[0].split()\n        \n        # نفتح ملف المعرفات للإضافة\n        with open(processed_file, \'a\', encoding=\'utf-8\') as f_ids:\n            \n            # نفحص آخر 10 رسائل مرسلة\n            for msg_num in sent_msg_ids[-10:]:\n                _, data = mail.fetch(msg_num, "(RFC822)")\n                raw_email = data[0][1]\n                msg = email.message_from_bytes(raw_email)\n                \n                # 1. استخراج المعرف الفريد (Message-ID)\n                unique_id = msg.get("Message-ID", "").strip()\n                \n                # 🛑 نقطة الحماية: إذا كان المعرف مسجلاً، تجاهله فوراً\n                if unique_id in processed_ids:\n                    continue \n\n                # إذا لم يكن مكرراً، نبدأ المعالجة\n                sent_body = ""\n                if msg.is_multipart():\n                    for part in msg.walk():\n                        if part.get_content_type() == "text/plain":\n                            sent_body = safe_decode(part.get_payload(decode=True))\n                            break\n                else:\n                    sent_body = safe_decode(msg.get_payload(decode=True))\n                \n                if not sent_body: continue\n\n                # البحث عن الإيميل الأصلي\n                references = []\n                if msg["In-Reply-To"]: references.append(msg["In-Reply-To"].strip())\n                if msg["References"]: references.extend(msg["References"].split())\n                \n                found_original = False\n                original_intent = None\n                original_text = ""\n\n                if references and history_content:\n                    blocks = history_content.split("إيميل وارد بتاريخ")\n                    for block in blocks:\n                        for ref in references:\n                            clean_ref = ref.strip(\'<> \')\n                            if clean_ref in block:\n                                found_original = True\n                                original_text = block\n                                intent_match = re.search(r"Org-Intent:\\s*(\\w+)", block)\n                                if intent_match:\n                                    original_intent = intent_match.group(1)\n                                break\n                        if found_original: break\n                \n                # إذا وجدنا الأصل، نتعلم منه\n                if found_original:\n                    print(f"✅ تم اكتشاف رد جديد (ID: {unique_id}) .. جاري التعلم...")\n                    update_email_history("إيميل صادر (رد المدير)", sent_body)\n                    \n                    if original_intent and original_intent in ["ADMIN", "HR", "RAG_MAINTENANCE" ,"User_Requests" ,]:\n                        new_rule = deduce_administrative_rule(original_text, sent_body, original_intent)\n                        if new_rule:\n                            update_intent_rules_file(original_intent, new_rule)\n                            updates_made = True # حدثنا القواعد\n                \n                # ✅ أهم خطوة: تسجيل المعرف في القائمة السوداء حتى لا نعالجه مستقبلاً\n                if unique_id:\n                    processed_ids.add(unique_id)\n                    f_ids.write(unique_id + "\\n")\n\n        mail.logout()\n        return updates_made # نعيد True فقط إذا تعلمنا قاعدة جديدة\n\n    except Exception as e:\n        print(f"⚠ خطأ في المزامنة: {e}")\n        return False\n')


